import os
import json
from pathlib import Path

# Read both policy documents
policy_files = []
for file in os.listdir('.'):
    if file.endswith('.json') and 'policy' in file.lower():
        policy_files.append(file)

print(f"Found policy files: {policy_files}")

policies = {}
for policy_file in policy_files:
    try:
        with open(policy_file, 'r', encoding='utf-8') as f:
            policies[policy_file] = json.load(f)
        print(f"Successfully loaded {policy_file}")
    except Exception as e:
        print(f"Error loading {policy_file}: {e}")

# Analyze and determine authoritative policy
if len(policies) == 0:
    print("No policy documents found")
elif len(policies) == 1:
    print(f"Only one policy document found: {list(policies.keys())[0]}")
    print("This is the authoritative policy by default")
else:
    print("\nAnalyzing multiple policy documents...")

    # Check for version information
    for filename, policy in policies.items():
        print(f"\n{filename}:")
        if 'version' in policy:
            print(f"  Version: {policy['version']}")
        if 'effective_date' in policy:
            print(f"  Effective Date: {policy['effective_date']}")
        if 'policy_name' in policy:
            print(f"  Policy Name: {policy['policy_name']}")

    # Determine authoritative policy based on criteria
    authoritative_policy = None
    max_version = None
    latest_date = None

    for filename, policy in policies.items():
        # Check version
        if 'version' in policy:
            if max_version is None or policy['version'] > max_version:
                max_version = policy['version']
                authoritative_policy = filename

        # Check effective date
        if 'effective_date' in policy:
            if latest_date is None or policy['effective_date'] > latest_date:
                latest_date = policy['effective_date']
                authoritative_policy = filename

    if authoritative_policy:
        print(f"\nAuthoritative policy determined: {authoritative_policy}")
        print("Criteria: Most recent version or effective date")
    else:
        # Fallback: use the first policy or check for other indicators
        print("\nCould not determine authoritative policy based on version/date")
        print("Using first policy as default authoritative document")
        authoritative_policy = list(policies.keys())[0]
        print(f"Default authoritative policy: {authoritative_policy}")
